# Let me verify the UNSAT result more carefully
# First, let's check if the degree constraints are being encoded correctly

from pysat.solvers import Glucose3
from pysat.card import *
from itertools import combinations

n = 15

edge_vars = {}
var_count = 0
for i in range(n):
    for j in range(i+1, n):
        edge_vars[(i,j)] = var_count + 1
        var_count += 1

# Test 1: Just no triangles, no 4-cycles, min degree 3
solver = Glucose3()

# No triangles
for i, j, k in combinations(range(n), 3):
    e1 = edge_vars[(min(i,j), max(i,j))]
    e2 = edge_vars[(min(j,k), max(j,k))]
    e3 = edge_vars[(min(i,k), max(i,k))]
    solver.add_clause([-e1, -e2, -e3])

# No 4-cycles
for i, j, k, l in combinations(range(n), 4):
    cycles = [
        [(i,j), (j,k), (k,l), (i,l)],
        [(i,j), (j,l), (l,k), (i,k)],
        [(i,k), (k,j), (j,l), (i,l)]
    ]
    for cycle in cycles:
        edges = []
        for u, v in cycle:
            edges.append(edge_vars[(min(u,v), max(u,v))])
        solver.add_clause([-e for e in edges])

# Min degree 3 (at least)
for i in range(n):
    edges_i = []
    for j in range(n):
        if i < j:
            edges_i.append(edge_vars[(i,j)])
        elif j < i:
            edges_i.append(edge_vars[(j,i)])

    for clause in CardEnc.atleast(lits=edges_i, bound=3, encoding=1):
        solver.add_clause(clause)

print("Test 1: No triangles, no 4-cycles, min degree 3")
if solver.solve():
    model = solver.get_model()
    edges = []
    for (i,j), var in edge_vars.items():
        if model[var-1] > 0:
            edges.append((i,j))
    print(f"SAT! Edges: {len(edges)}")

    # Check degrees
    degrees = [0]*n
    for u, v in edges:
        degrees[u] += 1
        degrees[v] += 1
    print(f"Degrees: {degrees}")
    print(f"Min degree: {min(degrees)}")
else:
    print("UNSAT")
